EOF
echo "exit=$?" && echo "---ledger---" && sqlite3 db/app.db "SELECT * FROM schema_migrations ORDER BY version;" && echo "---users_v2 cols---" && sqlite3 db/app.db "PRAGMA table_info(users_v2);""}

